                    if (g_amb[k].o == o) break;
                if (k == g_amb_n && g_amb_n < 16) {
                    g_amb[k].o = o;
                    g_amb[k].id = id;
                    g_amb[k].minr = 0x7FFFFFFF;
                    g_amb[k].minfr = -1;
                    g_amb[k].thresh = *(int *)(o + 0xbc);
                    g_amb[k].p0[0] = *(int *)(o + 0x5c);
                    g_amb[k].p0[1] = *(int *)(o + 0x60);
                    g_amb[k].p0[2] = *(int *)(o + 0x64);
                    ++g_amb_n;
                }
